os_error_t os_command_parse(const char *cmd, size_t n, uint8_t ch, char *reply, size_t z, size_t *rn) { char s[OS_MAX_COMMAND_LENGTH], out[64]; os_equatorial_coord_t c; os_error_t e = OS_ERR_COMMAND_FORMAT; if (!cmd || !reply || !rn) return OS_ERR_INVALID_ARGUMENT; *rn = 0; if (!valid_channel(ch) || n < 3 || n > OS_MAX_COMMAND_LENGTH || cmd[0] != ':' || cmd[n - 1] != '#') { reply_error(reply, z, rn, OS_ERR_COMMAND_FORMAT); return OS_ERR_COMMAND_FORMAT; } if (n - 2 >= sizeof s) { reply_error(reply, z, rn, OS_ERR_COMMAND_FORMAT); return OS_ERR_COMMAND_FORMAT; } memcpy(s, cmd + 1, n - 2); s[n - 2] = 0; if (!strcmp(s, "GVP")) reply_text(reply, z, rn, "OnStep 1.0.0#"); else if (!strcmp(s, "GR")) { os_query_coordinates(&c); snprintf(out, sizeof out, "%02d:%02d:%02d#", (int)c.ra_hours, (int)(c.ra_hours * 60) % 60, (int)(c.ra_hours * 3600) % 60); reply_text(reply, z, rn, out); } else if (!strcmp(s, "GD")) { double x; os_query_coordinates(&c); x = fabs(c.dec_degrees); snprintf(out, sizeof out, "%c%02d*%02d:%02d#", c.dec_degrees < 0 ? '-' : '+', (int)x, (int)(x * 60) % 60, (int)(x * 3600) % 60); reply_text(reply, z, rn, out); } else if (s[0] == 'S' && s[1] == 'r') { e = parse_ra(s + 2, &set_ra) ? OS_ERR_NONE : OS_ERR_INVALID_ARGUMENT; if (e == OS_ERR_NONE) reply_text(reply, z, rn, "1#"); } else if (s[0] == 'S' && s[1] == 'd') { e = parse_dec(s + 2, &set_dec) ? OS_ERR_NONE : OS_ERR_INVALID_ARGUMENT; if (e == OS_ERR_NONE) reply_text(reply, z, rn, "1#"); } else if (!strcmp(s, "MS")) { c.ra_hours = set_ra; c.dec_degrees = set_dec; e = os_goto_equatorial(c); reply_text(reply, z, rn, e == OS_ERR_NONE ? "0#" : "1#"); } else if (!strcmp(s, "Q")) { e = state == OS_STATE_GOTO ? os_goto_abort() : os_move_stop(); reply_text(reply, z, rn, "1#"); } else if (!strcmp(s, "hP")) { e = os_park(); reply_text(reply, z, rn, e == OS_ERR_NONE ? "1#" : "0#"); } else if (!strcmp(s, "hO")) { e = os_unpark(); reply_text(reply, z, rn, e == OS_ERR_NONE ? "1#" : "0#"); } else if (s[0] == 'M' && s[1]) { os_direction_t d; if (s[1] == 'e') d = OS_DIRECTION_EAST; else if (s[1] == 'w') d = OS_DIRECTION_WEST; else if (s[1] == 'n') d = OS_DIRECTION_NORTH; else if (s[1] == 's') d = OS_DIRECTION_SOUTH; else { reply_error(reply, z, rn, OS_ERR_COMMAND_FORMAT); return OS_ERR_COMMAND_FORMAT; } e = os_move_start(d, OS_SPEED_MEDIUM); reply_text(reply, z, rn, e == OS_ERR_NONE ? "1#" : "0#"); } else reply_error(reply, z, rn, e); if (!*rn) reply_error(reply, z, rn, e); return e; }
os_error_t os_goto_equatorial(os_equatorial_coord_t t) { os_motor_position_t p, q; int64_t a, b; if (!valid_eq(t)) return OS_ERR_INVALID_ARGUMENT; if (state == OS_STATE_PARKED || state == OS_STATE_FAULT || state == OS_STATE_ALIGNMENT) return OS_ERR_INVALID_STATE; p = raw_position(); q = to_steps(t, &calibration); a = (int64_t)q.ra_steps - p.ra_steps; b = (int64_t)q.dec_steps - p.dec_steps; if ((a && blocked(0, a > 0)) || (b && blocked(1, b > 0))) return OS_ERR_LIMIT_TRIGGERED; target_coord = t; if (llabs(a) <= 2 && llabs(b) <= 2) { current_coord = t; return OS_ERR_NONE; } memset(&motion, 0, sizeof motion); motion.active = true; motion.target = q; state = OS_STATE_GOTO; stop_axis(0); stop_axis(1); return OS_ERR_NONE; }
os_error_t os_goto_horizontal(os_horizontal_coord_t t) { os_equatorial_coord_t e; if (!finitef(t.azimuth_degrees) || !finitef(t.altitude_degrees) || t.azimuth_degrees < 0 || t.azimuth_degrees > 360 || t.altitude_degrees < -90 || t.altitude_degrees > 90) return OS_ERR_INVALID_ARGUMENT; if (!time_valid || !site.valid) return OS_ERR_INVALID_STATE; if (OS_MOUNT_TYPE == OS_MOUNT_ALTAZ) e = horizontal_to_eq(t); else { e.ra_hours = t.azimuth_degrees / 15.0f; e.dec_degrees = t.altitude_degrees; } return os_goto_equatorial(e); }
os_error_t os_goto_abort(void) { if (state != OS_STATE_GOTO) return OS_ERR_INVALID_STATE; stop_motion(); state = OS_STATE_IDLE_TRACKING; return tracking_outputs(); }
os_error_t os_tracking_set_rate(os_track_rate_t r, float f) { os_error_t e; if (r < OS_TRACK_RATE_SIDEREAL || r > OS_TRACK_RATE_CUSTOM || !finitef(f) || (r == OS_TRACK_RATE_CUSTOM && f <= 0)) return OS_ERR_INVALID_ARGUMENT; track_rate = r; if (r == OS_TRACK_RATE_CUSTOM) custom_factor = f; e = save_cfg(); if (e != OS_ERR_NONE) return OS_ERR_NVM_FAULT; return tracking_outputs(); }
os_error_t os_tracking_get_rate(os_track_rate_t *r, float *f) { if (!r || !f) return OS_ERR_INVALID_ARGUMENT; *r = track_rate; *f = custom_factor; return OS_ERR_NONE; }
os_error_t os_tracking_enable(void) { if (state == OS_STATE_PARKED || state == OS_STATE_FAULT || !time_valid) return OS_ERR_INVALID_STATE; tracking_enabled = true; return tracking_outputs(); }
os_error_t os_tracking_disable(void) { tracking_enabled = false; stop_axis(0); stop_axis(1); return OS_ERR_NONE; }
os_error_t os_guide_pulse(os_direction_t d, uint32_t ms) { if (!valid_direction(d) || ms == 0) return OS_ERR_INVALID_ARGUMENT; if (state == OS_STATE_PARKED || state == OS_STATE_FAULT) return OS_ERR_INVALID_STATE; if (guide.active && guide.dec_priority && (d == OS_DIRECTION_EAST || d == OS_DIRECTION_WEST)) return OS_ERR_INVALID_STATE; memset(&guide, 0, sizeof guide); guide.active = true; guide.duration_ms = ms; guide.rate_fraction = guide_rate; guide.direction_east = d == OS_DIRECTION_EAST; guide.direction_north = d == OS_DIRECTION_NORTH; guide.dec_priority = d == OS_DIRECTION_NORTH || d == OS_DIRECTION_SOUTH; guide_direction = d; guide_left = ms; return tracking_outputs(); }
os_error_t os_guide_set_rate(float f) { os_error_t e; if (!finitef(f) || f < OS_GUIDE_RATE_MIN || f > OS_GUIDE_RATE_MAX) return OS_ERR_INVALID_ARGUMENT; guide_rate = f; e = save_cfg(); return e == OS_ERR_NONE ? OS_ERR_NONE : OS_ERR_NVM_FAULT; }
os_error_t os_guide_get_state(os_guide_pulse_t *p) { if (!p) return OS_ERR_INVALID_ARGUMENT; *p = guide; return OS_ERR_NONE; }
os_error_t os_align_begin(os_align_mode_t m) { if (m < OS_ALIGN_1STAR || m > OS_ALIGN_NSTAR) return OS_ERR_INVALID_ARGUMENT; align_mode = m; align_count = 0; residual_valid = false; state = OS_STATE_ALIGNMENT; stop_motion(); return OS_ERR_NONE; }
os_error_t os_align_accept_star(os_equatorial_coord_t c, os_motor_position_t p) { if (!valid_eq(c)) return OS_ERR_INVALID_ARGUMENT; if (state != OS_STATE_ALIGNMENT || align_count >= OS_CALIBRATION_MAX_STARS) return OS_ERR_INVALID_STATE; stars[align_count].c = c; stars[align_count].p = p; ++align_count; return OS_ERR_NONE; }
static bool solve3(double a[3][4], double x[3]) { int i, j, k, p; double t, m, q; for (i = 0; i < 3; ++i) { p = i; for (j = i + 1; j < 3; ++j) if (fabs(a[j][i]) > fabs(a[p][i])) p = j; if (fabs(a[p][i]) < 1e-12) return false; if (p != i) for (k = i; k < 4; ++k) { t = a[i][k]; a[i][k] = a[p][k]; a[p][k] = t; } for (j = i + 1; j < 3; ++j) { m = a[j][i] / a[i][i]; for (k = i; k < 4; ++k) a[j][k] -= m * a[i][k]; } } for (i = 2; i >= 0; --i) { q = a[i][3]; for (j = i + 1; j < 3; ++j) q -= a[i][j] * x[j]; x[i] = q / a[i][i]; } return true; }
os_error_t os_align_compute(void) { double a[3][4], x[3], y[3], det, rss = 0; os_calibration_t n; int i; uint8_t min = align_mode == OS_ALIGN_1STAR ? 1 : align_mode == OS_ALIGN_2STAR ? 2 : 3; if (align_count < min) return OS_ERR_INVALID_STATE; memset(&n, 0, sizeof n); if (align_mode == OS_ALIGN_1STAR) { n.matrix_ra_to_ra = n.matrix_dec_to_dec = 1; n.offset_ra_arcsec = (float)(stars[0].p.ra_steps - ra_arcsec(stars[0].c) * OS_STEPS_PER_ARCSEC); n.offset_dec_arcsec = (float)(stars[0].p.dec_steps - dec_arcsec(stars[0].c) * OS_STEPS_PER_ARCSEC); } else if (align_mode == OS_ALIGN_2STAR) { double dr = ra_arcsec(stars[1].c) - ra_arcsec(stars[0].c), dd = dec_arcsec(stars[1].c) - dec_arcsec(stars[0].c); if (fabs(dr) < 1e-12 || fabs(dd) < 1e-12) return OS_ERR_CALIBRATION_FAILED; n.matrix_ra_to_ra = (float)((stars[1].p.ra_steps - stars[0].p.ra_steps) / (dr * OS_STEPS_PER_ARCSEC)); n.matrix_dec_to_dec = (float)((stars[1].p.dec_steps - stars[0].p.dec_steps) / (dd * OS_STEPS_PER_ARCSEC)); n.offset_ra_arcsec = (float)(stars[0].p.ra_steps / OS_STEPS_PER_ARCSEC - n.matrix_ra_to_ra * ra_arcsec(stars[0].c)); n.offset_dec_arcsec = (float)(stars[0].p.dec_steps / OS_STEPS_PER_ARCSEC - n.matrix_dec_to_dec * dec_arcsec(stars[0].c)); } else { for (i = 0; i < 3; ++i) { a[i][0] = ra_arcsec(stars[i].c); a[i][1] = dec_arcsec(stars[i].c); a[i][2] = 1; a[i][3] = stars[i].p.ra_steps / OS_STEPS_PER_ARCSEC; } det = (a[1][0] - a[0][0]) * (a[2][1] - a[0][1]) - (a[2][0] - a[0][0]) * (a[1][1] - a[0][1]); if (fabs(det) < 1e-12 * fmax(1.0, fabs(a[1][0] - a[0][0]) * fabs(a[2][1] - a[0][1]))) return OS_ERR_CALIBRATION_FAILED; if (!solve3(a, x)) return OS_ERR_CALIBRATION_FAILED; for (i = 0; i < 3; ++i) { a[i][0] = ra_arcsec(stars[i].c); a[i][1] = dec_arcsec(stars[i].c); a[i][2] = 1; a[i][3] = stars[i].p.dec_steps / OS_STEPS_PER_ARCSEC; } if (!solve3(a, y)) return OS_ERR_CALIBRATION_FAILED; n.matrix_ra_to_ra = (float)x[0]; n.matrix_dec_to_ra = (float)x[1]; n.offset_ra_arcsec = (float)x[2]; n.matrix_ra_to_dec = (float)y[0]; n.matrix_dec_to_dec = (float)y[1]; n.offset_dec_arcsec = (float)y[2]; } n.valid = true; for (i = 0; i < align_count; ++i) { os_motor_position_t p = to_steps(stars[i].c, &n); double u = p.ra_steps - stars[i].p.ra_steps, v = p.dec_steps - stars[i].p.dec_steps; rss += u * u + v * v; } residual = (float)sqrt(rss / align_count) / (float)OS_STEPS_PER_ARCSEC; if (align_count >= 4 && residual > 300.0f) return OS_ERR_CALIBRATION_FAILED; if (save_cal(&n) != OS_ERR_NONE) return OS_ERR_NVM_FAULT; calibration = n; residual_valid = true; state = OS_STATE_IDLE_TRACKING; return OS_ERR_NONE; }
os_error_t os_align_get_residual(float *r) { if (!r) return OS_ERR_INVALID_ARGUMENT; if (!residual_valid) return OS_ERR_INVALID_STATE; *r = residual; return OS_ERR_NONE; }
os_error_t os_align_abort(void) { if (state != OS_STATE_ALIGNMENT) return OS_ERR_INVALID_STATE; align_count = 0; residual_valid = false; state = OS_STATE_IDLE_TRACKING; return OS_ERR_NONE; }
os_error_t os_park(void) { os_error_t e; os_equatorial_coord_t p; if (os_hal_limit_is_triggered(0) || os_hal_limit_is_triggered(1)) return OS_ERR_LIMIT_TRIGGERED; p = custom_park ? park_coord : (os_equatorial_coord_t){0, 90}; e = os_goto_equatorial(p); if (e == OS_ERR_NONE && state == OS_STATE_GOTO) motion.parking = true; else if (e == OS_ERR_NONE) { tracking_enabled = false; state = OS_STATE_PARKED; stop_motion(); } return e; }
os_error_t os_unpark(void) { uint8_t i; uint32_t t; if (state != OS_STATE_PARKED) return OS_ERR_INVALID_STATE; for (i = 0; i < AXES; ++i) if (os_hal_motor_init(i) != OS_ERR_NONE) { state = OS_STATE_FAULT; return OS_ERR_MOTOR_DRIVER_FAULT; } for (i = 0; i < CHANNELS; ++i) (void)os_hal_comm_init(i); if (os_hal_rtc_read(&t) != OS_ERR_NONE) return OS_ERR_INVALID_STATE; site.utc_epoch_seconds = t; time_valid = true; tracking_enabled = true; state = OS_STATE_IDLE_TRACKING; return tracking_outputs(); }
os_error_t os_park_set_position(os_equatorial_coord_t p) { if (!valid_eq(p)) return OS_ERR_INVALID_ARGUMENT; park_coord = p; custom_park = true; return save_cfg() == OS_ERR_NONE ? OS_ERR_NONE : OS_ERR_NVM_FAULT; }
os_error_t os_move_start(os_direction_t d, os_speed_level_t s) { uint32_t f; if (!valid_direction(d) || s < OS_SPEED_SLOW || s > OS_SPEED_CUSTOM) return OS_ERR_INVALID_ARGUMENT; if (state == OS_STATE_PARKED || state == OS_STATE_FAULT) return OS_ERR_INVALID_STATE; manual.axis = (d == OS_DIRECTION_EAST || d == OS_DIRECTION_WEST) ? 0 : 1; manual.forward = d == OS_DIRECTION_EAST || d == OS_DIRECTION_NORTH; if (blocked(manual.axis, manual.forward)) return OS_ERR_LIMIT_TRIGGERED; f = frequency_for(s == OS_SPEED_SLOW ? OS_MANUAL_SPEED_SLOW_ARCSEC : s == OS_SPEED_MEDIUM ? OS_MANUAL_SPEED_MEDIUM_ARCSEC : s == OS_SPEED_FAST ? OS_MANUAL_SPEED_FAST_ARCSEC : custom_move_speed); manual.frequency = f; manual.active = true; manual_left = MANUAL_TIMEOUT_MS; state = OS_STATE_MANUAL_MOTION; return OS_ERR_NONE; }
os_error_t os_move_stop(void) { stop_motion(); if (state == OS_STATE_GOTO || state == OS_STATE_MANUAL_MOTION) state = OS_STATE_IDLE_TRACKING; return tracking_outputs(); }
os_error_t os_move_set_custom_speed(float s) { if (!finitef(s) || s <= 0) return OS_ERR_INVALID_ARGUMENT; custom_move_speed = s; return save_cfg() == OS_ERR_NONE ? OS_ERR_NONE : OS_ERR_NVM_FAULT; }
os_error_t os_query_state(os_state_t *p) { if (!p) return OS_ERR_INVALID_ARGUMENT; *p = state; return OS_ERR_NONE; }
os_error_t os_query_coordinates(os_equatorial_coord_t *p) { if (!p) return OS_ERR_INVALID_ARGUMENT; *p = from_steps(raw_position()); return OS_ERR_NONE; }
os_error_t os_query_site(os_site_info_t *p) { if (!p) return OS_ERR_INVALID_ARGUMENT; *p = site; return OS_ERR_NONE; }
os_error_t os_query_motor_position(os_motor_position_t *p) { if (!p) return OS_ERR_INVALID_ARGUMENT; *p = raw_position(); return OS_ERR_NONE; }
os_error_t os_query_firmware_version(uint8_t *a, uint8_t *b, uint8_t *c) { if (!a || !b || !c) return OS_ERR_INVALID_ARGUMENT; *a = OS_FIRMWARE_VERSION_MAJOR; *b = OS_FIRMWARE_VERSION_MINOR; *c = OS_FIRMWARE_VERSION_PATCH; return OS_ERR_NONE; }
os_error_t os_query_is_moving(bool *p) { if (!p) return OS_ERR_INVALID_ARGUMENT; *p = motion.active || manual.active || state == OS_STATE_GOTO || state == OS_STATE_MANUAL_MOTION; return OS_ERR_NONE; }
os_error_t os_query_gps_locked(bool *p) { if (!p) return OS_ERR_INVALID_ARGUMENT; *p = gps_locked; return OS_ERR_NONE; }
os_error_t os_pec_enable(bool e) { if (e && !pec.valid) return OS_ERR_INVALID_STATE; pec_enabled = e; return tracking_outputs(); }
os_error_t os_pec_load_table(const os_pec_table_t *p) { if (!p || !p->valid) return OS_ERR_INVALID_ARGUMENT; pec = *p; return os_hal_nvm_write(PEC_OFF, (const uint8_t *)&pec, sizeof pec) == OS_ERR_NONE ? OS_ERR_NONE : OS_ERR_NVM_FAULT; }
os_error_t os_pec_get_table(os_pec_table_t *p) { if (!p) return OS_ERR_INVALID_ARGUMENT; *p = pec; return OS_ERR_NONE; }
os_error_t os_pec_record_phase(float phase, int16_t error) { int i; if (!finitef(phase) || phase < 0 || phase > 360) return OS_ERR_INVALID_ARGUMENT; i = phase >= 360 ? 0 : (int)phase; pec.corrections[i] = error; pec.valid = true; return os_hal_nvm_write(PEC_OFF, (const uint8_t *)&pec, sizeof pec) == OS_ERR_NONE ? OS_ERR_NONE : OS_ERR_NVM_FAULT; }
os_error_t os_calibration_get(os_calibration_t *p) { if (!p) return OS_ERR_INVALID_ARGUMENT; *p = calibration; return OS_ERR_NONE; }
