os_error_t os_hal_motor_init(uint8_t a) { if (!valid_axis(a)) return OS_ERR_INVALID_ARGUMENT; h_motor_initialized[a] = true; h_motor_enabled[a] = false; h_motor_frequency[a] = 0; h_motor_remainder[a] = 0; return OS_ERR_NONE; }
os_error_t os_hal_motor_set_frequency(uint8_t a, uint32_t f) { if (!valid_axis(a) || !h_motor_initialized[a]) return OS_ERR_INVALID_ARGUMENT; if (f > OS_MAX_MOTOR_FREQUENCY_HZ) f = OS_MAX_MOTOR_FREQUENCY_HZ; h_motor_frequency[a] = f; return OS_ERR_NONE; }
os_error_t os_hal_motor_set_direction(uint8_t a, bool f) { if (!valid_axis(a) || !h_motor_initialized[a]) return OS_ERR_INVALID_ARGUMENT; h_motor_direction[a] = f; return OS_ERR_NONE; }
os_error_t os_hal_motor_enable(uint8_t a, bool e) { if (!valid_axis(a) || !h_motor_initialized[a]) return OS_ERR_INVALID_ARGUMENT; h_motor_enabled[a] = e; if (!e) h_motor_frequency[a] = 0; return OS_ERR_NONE; }
int32_t os_hal_motor_get_position(uint8_t a) { return valid_axis(a) ? h_motor_position[a] : 0; }
os_error_t os_hal_gps_init(void) { h_gps_ready = true; return OS_ERR_NONE; }
os_error_t os_hal_gps_poll(os_site_info_t *p) { if (!p) return OS_ERR_INVALID_ARGUMENT; if (!h_gps_ready || !h_gps_site.valid) { memset(p, 0, sizeof *p); return OS_ERR_GPS_NO_SIGNAL; } *p = h_gps_site; return OS_ERR_NONE; }
