os_error_t os_hal_rtc_read(uint32_t *p) { if (!p) return OS_ERR_INVALID_ARGUMENT; if (!h_rtc_ready) return OS_ERR_TIMEOUT; *p = h_rtc_epoch; return OS_ERR_NONE; }
os_error_t os_hal_rtc_set(uint32_t t) { if (!h_rtc_ready) return OS_ERR_TIMEOUT; h_rtc_epoch = t; return OS_ERR_NONE; }
os_error_t os_hal_limit_init(void) { return OS_ERR_NONE; }
bool os_hal_limit_is_triggered(uint8_t a) { return !valid_axis(a) || h_limit[a]; }
os_error_t os_hal_nvm_init(void) { h_nvm_ready = true; return OS_ERR_NONE; }
os_error_t os_hal_nvm_read(uint16_t o, uint8_t *p, uint16_t n) { if (!p) return OS_ERR_INVALID_ARGUMENT; if (!h_nvm_ready) return OS_ERR_NVM_FAULT; if ((uint32_t)o + n > NVM_TOTAL) return OS_ERR_INVALID_ARGUMENT; memcpy(p, h_nvm + o, n); return OS_ERR_NONE; }
os_error_t os_hal_nvm_write(uint16_t o, const uint8_t *p, uint16_t n) { if (!p) return OS_ERR_INVALID_ARGUMENT; if (!h_nvm_ready) return OS_ERR_NVM_FAULT; if ((uint32_t)o + n > NVM_TOTAL) return OS_ERR_INVALID_ARGUMENT; memcpy(h_nvm + o, p, n); return OS_ERR_NONE; }
os_error_t os_hal_comm_init(uint8_t c) { if (!valid_channel(c)) return OS_ERR_INVALID_ARGUMENT; h_rx_head[c] = h_rx_tail[c] = h_tx_length[c] = 0; return OS_ERR_NONE; }
int16_t os_hal_comm_available(uint8_t c) { if (!valid_channel(c)) return -1; return (int16_t)(h_rx_tail[c] - h_rx_head[c]); }
char os_hal_comm_read(uint8_t c) { size_t i; if (!valid_channel(c) || h_rx_head[c] >= h_rx_tail[c]) return 0; i = h_rx_head[c]++ % sizeof h_rx[c]; return h_rx[c][i]; }
os_error_t os_hal_comm_write(uint8_t c, const char *p, size_t n) { if (!valid_channel(c) || !p) return OS_ERR_INVALID_ARGUMENT; if (n > sizeof h_tx[c] - h_tx_length[c]) return OS_ERR_TIMEOUT; memcpy(h_tx[c] + h_tx_length[c], p, n); h_tx_length[c] += n; return OS_ERR_NONE; }
os_error_t os_hal_buzzer_beep(uint16_t d, uint8_t n) { uint8_t next; if (!n) return OS_ERR_NONE; next = (uint8_t)((h_buzzer_tail + 1u) % 8u); if (next == h_buzzer_head) return OS_ERR_TIMEOUT; h_buzzer[h_buzzer_tail].duration = d; h_buzzer[h_buzzer_tail].count = n; h_buzzer_tail = next; return OS_ERR_NONE; }
os_error_t os_hal_timer_motor_init(void) { memset(h_motor_remainder, 0, sizeof h_motor_remainder); return OS_ERR_NONE; }